bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createVideoBotScreenTransport} from './src/telegram/creatorScreenTransport.mjs';
import {createStickerSalesFlow} from './src/telegram/stickerSales.mjs';
import {createPostgresCreatorSessionStore} from './src/sales/pgCreatorSessions.mjs';
import {createPostgresStickerInventory} from './src/stickers/pgStickerInventory.mjs';
import {createPostgresStickerSales} from './src/stickers/pgStickerSales.mjs';
const e=process.env;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,
 user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const q=await pool.query(`SELECT owner_user_id,revision,screen_message_id,
 state->'stickerSale'->>'packName' AS pack_name FROM videobot_creator_sessions
 WHERE state->>'screen'='sticker_sale_price' AND state->'stickerSale'->>'mode'='seller'`);
 if(q.rows.length===0){process.stdout.write('STK03_NO_LEGACY_PRICE_SCREEN=PASS\n');}
 else if(q.rows.length!==1){throw Error('STK03_AMBIGUOUS_LEGACY_PRICE_SCREEN');}
 else {
  const row=q.rows[0],owner=Number(row.owner_user_id);
  if(!Number.isSafeInteger(owner)||owner<=0||!Number.isSafeInteger(Number(row.revision))||
     !Number.isSafeInteger(Number(row.screen_message_id))||Number(row.screen_message_id)<=0||
     typeof row.pack_name!=='string'||!row.pack_name)throw Error('STK03_SCREEN_PRECHECK_FAILED');
  const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
  const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:15000});
  const me=await api('getMe',{});
  if(me?.is_bot!==true||String(me.username||'').toLowerCase()!=='createvdobot')
   throw Error('STK03_BOT_IDENTITY_UNVERIFIED');
  const sessionStore=createPostgresCreatorSessionStore(pool);
  const current=await sessionStore.read(owner);
  if(current?.screen!=='sticker_sale_price'||current.revision!==Number(row.revision)||
     current.screenMessageId!==Number(row.screen_message_id)||
     current.stickerSale?.mode!=='seller'||current.stickerSale?.packName!==row.pack_name)
    throw Error('STK03_SCREEN_RACE_ABORT');
  const flow=createStickerSalesFlow({
   api,sessionStore,screenTransport:createVideoBotScreenTransport(api),
   salesStore:createPostgresStickerSales(pool),packInventory:createPostgresStickerInventory(pool),
   publishSnapshot:async()=>{throw Error('STK03_NO_PUBLICATION_IN_REFRESH');}
  });
  const result=await flow.beginSell({ownerId:owner,packName:row.pack_name});
  if(result?.handled!==true||result.locked===true)throw Error('STK03_SCREEN_REFRESH_BLOCKED');
  const after=await sessionStore.read(owner);
  if(after?.screen!=='sticker_sale_price'||after.revision!==current.revision+1||
     !Number.isSafeInteger(after.screenMessageId)||after.screenMessageId<=0)
   throw Error('STK03_SCREEN_REFRESH_NOT_DURABLE');
  process.stdout.write('STK03_EXISTING_DM_PRICE_BUTTONS_REFRESHED=PASS\n');
 }
}finally{await outgoing.close();await pool.end();}
NODE
